# Builds the MLOps experiment board (report/datascape_board.html) from the single sources of truth:
# work/experiments.csv (every scenario, ranked), submissions/ledger.csv (expected vs actual LB), work/pl_iter_scores.csv,
# work/probe9_scores.csv (if present), work/sessions.csv. Re-run after every LB result or experiment, then republish.
import json, os, re, pandas as pd
EVID = {'LB paired': 0, 'LB probe (pending 10-05)': 1, 'LB single': 2, 'test-domain held-out': 3, 'test-domain': 3, 'OOF honest + LB': 0,
        'OOF honest': 4, 'OOF vs LB': 4, 'OOF honest (cleaned)': 5, 'OOF leaky': 6, 'audit': 7, 'count': 7, 'design': 8}
def num(s):
    m = re.search(r'-?\+?\d*\.\d+', str(s)); return float(m.group()) if m else None
E = pd.read_csv('work/experiments.csv').fillna('')
E['rank_evidence'] = E.evidence.map(EVID).fillna(9); E['lb_num'] = E.lb_public.map(num); E['oof_num'] = E.metric_oof_orig.map(num)
E = E.sort_values(['rank_evidence', 'lb_num', 'oof_num'], ascending=[True, False, False], na_position='last').reset_index(drop=True); E['rank'] = E.index + 1
L = pd.read_csv('submissions/ledger.csv')
L = L[['name', 'created_utc', 'strategy', 'oof_macro_f1', 'expected_lb', 'exp_lo', 'exp_hi', 'pred_mix', 'submitted_utc', 'actual_lb']].fillna('')
extra = {}
for f, k in [('work/pl_iter_scores.csv', 'pl'), ('work/probe9_scores.csv', 'probe9'), ('work/sessions.csv', 'sessions'), ('work/copy_structure.csv', 'copies')]:
    if os.path.exists(f): extra[k] = pd.read_csv(f).fillna('').to_dict('records')
data = dict(experiments=E.drop(columns=['rank_evidence', 'lb_num', 'oof_num']).to_dict('records'), ledger=L.to_dict('records'), **extra,
            share_trend=[dict(share=0.42, lb=0.768), dict(share=0.39, lb=0.786), dict(share=0.35, lb=0.79), dict(share=0.30, lb=0.821), dict(share=0.274, lb=0.830)],
            updated=pd.Timestamp.utcnow().strftime('%Y-%m-%d %H:%M UTC'))
os.makedirs('report', exist_ok=True); tpl = open('report/board_template.html').read()
open('report/datascape_board.html', 'w').write(tpl.replace('/*DATA*/null', json.dumps(data, default=str)))
print('board written', len(E), 'experiments', len(L), 'ledger rows', list(extra))

# Markdown twin of the board for GitHub (report/REPORT.md): same sources, same ranking.
def mdt(rows, cols, head):
    if not rows: return '_not available_\n'
    esc = lambda v: str(v).replace('|', '\\|').replace('\n', ' ')
    return '| ' + ' | '.join(head) + ' |\n|' + '---|' * len(cols) + '\n' + ''.join('| ' + ' | '.join(esc(r.get(c, '')) for c in cols) + ' |\n' for r in rows)
ex = data['experiments']; led = [r for r in data['ledger'] if r['expected_lb'] != '']
md = [f"# Datascape 2026 experiment report\n\nUpdated {data['updated']}. Generated by `work/build_report.py` from `work/experiments.csv`, `submissions/ledger.csv` and the score CSVs. Ranking = strength of evidence (paired LB > LB probe > single LB > test-domain held-out > honest group-OOF vs original labels > cleaned/leaky OOF > audit).\n",
      '## Scenario ranking\n', mdt(ex, ['rank', 'category', 'experiment', 'metric_oof_orig', 'test_domain_metric', 'lb_public', 'expected_lb', 'evidence', 'decision', 'notes'],
                                 ['#', 'Category', 'Scenario', 'OOF orig', 'Test-domain', 'LB', 'Exp. LB', 'Evidence', 'Decision', 'Notes']),
      '\n## Submissions: expected vs actual\n', mdt(led, ['name', 'oof_macro_f1', 'expected_lb', 'exp_lo', 'exp_hi', 'actual_lb', 'submitted_utc'], ['Name', 'OOF', 'Expected', 'Low', 'High', 'Actual LB', 'Submitted (UTC)']),
      '\n## Duplicates and leakage (pixel-exact copies, NCC >= 0.99)\n', mdt(data.get('copies'), list(data['copies'][0]) if data.get('copies') else [], list(data['copies'][0]) if data.get('copies') else []),
      '\n## Frozen-tower gate (added to cat6+PE-G; bar +0.005)\n', mdt(data.get('probe9'), ['tag', 'f1_orig', 'f1_clean', 'test_rusak', 'f1_twin_locked'], ['Config', 'OOF orig', 'OOF cleaned', 'Test Rusak', 'Twin-locked F1']),
      '\n## Iterative pseudo-labelling (held-out locked test rows; bar +0.005)\n', mdt(data.get('pl'), ['round', 'pseudo_rows', 'heldout_f1', 'heldout_f1_b08', 'unlocked_rusak_b08'], ['Round', 'Pseudo rows', 'F1', 'F1 @ bias -0.8', 'Unlocked Rusak share']),
      '\n## Compute log (Colab Pro A100)\n', mdt(data.get('sessions'), ['session', 'date', 'minutes', 'job', 'outcome'], ['#', 'Date', 'Min', 'Job', 'Outcome'])]
open('report/REPORT.md', 'w').write('\n'.join(md)); print('report/REPORT.md written')
